judgment.answer:
一种做法是利用阶乘分组：固定当前位后，剩余数字有 \((m-1)!\) 种排列。先把 \(k\) 转成从 0 开始的索引，再据此选择每一位的数字。

```cpp
#include <string>
#include <vector>
using namespace std;

class Solution {
public:
    string getPermutation(int n, int k) {
        vector<int> factorial(n, 1);
        for (int i = 1; i < n; ++i) {
            factorial[i] = factorial[i - 1] * i;
        }

        vector<int> nums;
        for (int i = 1; i <= n; ++i) {
            nums.push_back(i);
        }

        --k;  // 转为 0-based
        string result;

        for (int remaining = n; remaining >= 1; --remaining) {
            int blockSize = factorial[remaining - 1];
            int index = k / blockSize;

            result.push_back(char('0' + nums[index]));
            nums.erase(nums.begin() + index);
            k %= blockSize;
        }

        return result;
    }
};
```

在题目约束 \(n \le 9\) 下，将数字转成字符是有效的；逐次从数组中删除元素的时间复杂度为 \(O(n^2)\)。

