## Example answer

In UE5, `FAudioCapture` provides audio capture without an `AudioCaptureComponent`. Enable the **Audio Capture** plugin and add its module to your project’s `Build.cs`. The exact API can vary slightly by engine version; a typical UE5 setup looks like this:

```cpp
// MyGameMode.h
#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "AudioCapture.h"
#include "MyGameMode.generated.h"

UCLASS()
class YOURGAME_API AMyGameMode : public AGameModeBase
{
    GENERATED_BODY()

public:
    virtual void BeginPlay() override;
    virtual void EndPlay(const EEndPlayReason::Type EndPlayReason) override;

private:
    Audio::FAudioCapture Capture;
    bool bStreamOpen = false;
};
```

```cpp
// MyGameMode.cpp
#include "MyGameMode.h"

void AMyGameMode::BeginPlay()
{
    Super::BeginPlay();

    Audio::FAudioCaptureDeviceParams Params;
    Params.DeviceIndex = INDEX_NONE; // Default input device
    Params.NumChannels = 1;
    Params.SampleRate = 48000;

    const bool bOpened = Capture.OpenAudioCaptureStream(
        Params,
        [](const float* AudioData,
           int32 NumFrames,
           int32 NumChannels,
           int32 SampleRate,
           double StreamTime,
           bool bOverflow)
        {
            // Called with captured audio, typically on an audio thread.
            // Copy data here if it needs to outlive this callback.
            // Avoid calling gameplay/UObject code directly from this callback.
        },
        1024); // Requested frames per callback

    if (!bOpened)
    {
        UE_LOG(LogTemp, Error, TEXT("Could not open audio capture stream."));
        return;
    }

    bStreamOpen = true;

    if (!Capture.StartStream())
    {
        UE_LOG(LogTemp, Error, TEXT("Could not start audio capture stream."));
        Capture.CloseStream();
        bStreamOpen = false;
    }
}

void AMyGameMode::EndPlay(const EEndPlayReason::Type EndPlayReason)
{
    if (bStreamOpen)
    {
        Capture.StopStream();
        Capture.CloseStream();
        bStreamOpen = false;
    }

    Super::EndPlay(EndPlayReason);
